def content(t):
 def v(key): return e(t[key])
 cards=''.join(f'<article><span>{v("s"+str(i))}</span><h3>{v("h"+str(i))}</h3><p>{v("p"+str(i))}</p></article>' for i in range(1,5))
 steps=''.join(f'<div><span>0{i}</span><h3>{v("step"+str(i))}</h3><p>{v("stepp"+str(i))}</p></div>' for i in range(1,4))
 return f'''<section class="page-heading agency-heading"><p class="eyebrow dark">{v('eyebrow')}</p><h1>{v('hero_a')}<br><em>{v('hero_b')}</em></h1><p>{v('hero')}</p><div class="actions"><a class="button dark" href="mailto:press@aurora-studio.org?subject=ACG%20partnership%20enquiry">{v('talk')} ↗</a><a class="text-link" href="#approach">{v('how')} ↓</a></div></section><section class="section agency-intro" id="approach"><div><p class="eyebrow dark">{v('opportunity')}</p><h2>{v('idea_a')}<br>{v('idea_b')}</h2></div><div><p>{v('intro1')}</p><p>{v('intro2')}</p></div></section><section class="section agency-services"><div class="section-head"><p class="eyebrow dark">{v('support')}</p><span>{v('scope')}</span></div><div class="agency-grid">{cards}</div></section><section class="agency-band"><div class="section"><p class="eyebrow">{v('band')}</p><h2>{v('bandh')}</h2><p>{v('bandp')}</p></div></section><section class="section agency-proof"><div><p class="eyebrow dark">{v('experience')}</p><h2>{v('proofh')}</h2><p>{v('proofp')}</p><a href="/media/#numazu">{v('prooflink')} ↗ (EN)</a></div><div class="agency-proof-card"><span>PROJECT NUMAZU / 2026</span><h3>{v('card')}</h3><p>{v('cardp')}</p><a href="/project/project-numazu/">{v('cardlink')} ↗ (EN)</a></div></section><section class="section agency-process"><p class="eyebrow dark">{v('process')}</p>{steps}</section><section class="callout"><p class="eyebrow">{v('ctaeye')}</p><h2>{t['ctah']}</h2><p>{v('ctap')}</p><a class="button light" href="mailto:press@aurora-studio.org?subject=ACG%20partnership%20enquiry">{v('email')} ↗</a><p class="agency-note">{v('note')}</p></section>'''

def generate(page):
 for route,t in COPY.items():
  page(t['title'],t['description'],content(t),f'{route}/acg-partnerships/index.html',lang=t['lang'])
